// Embeds recipes/*.yaml into lib/src/recipes/bundled_recipes.g.dart.
//
// Why: files outside lib/ can't be read reliably once plumb is installed with
// `dart pub global activate` or compiled with `dart compile exe`. The YAML in
// recipes/ stays the source of truth; a test fails if the generated file is
// stale.
//
// Usage: dart run tool/generate_bundled_recipes.dart
import 'dart:io';

import 'package:path/path.dart' as p;

/// Where the generated Dart file lives.
const generatedPath = 'lib/src/recipes/bundled_recipes.g.dart';

void main() {
  File(
    generatedPath,
  ).writeAsStringSync(generateBundledRecipes(readRecipeFiles()));
  stdout.writeln('Wrote $generatedPath');
}

/// Reads `recipes/*.yaml` as file name → contents, sorted by name.
Map<String, String> readRecipeFiles([String directory = 'recipes']) {
  final dir = Directory(directory);
  if (!dir.existsSync()) return {};
  final files =
      dir
          .listSync()
          .whereType<File>()
          .where((f) => f.path.endsWith('.yaml'))
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));
  return {
    for (final file in files)
      p.basename(file.path): file.readAsStringSync().replaceAll('\r\n', '\n'),
  };
}

/// Returns the Dart source embedding [files]. Output is already in
/// `dart format` style so formatting the repo never changes it.
String generateBundledRecipes(Map<String, String> files) {
  final buffer = StringBuffer()
    ..writeln(
      '// GENERATED by tool/generate_bundled_recipes.dart from recipes/*.yaml.',
    )
    ..writeln('// Do not edit by hand; edit the YAML and re-run the tool.')
    ..writeln()
    ..writeln('/// Bundled recipe files: file name → YAML contents.');
  if (files.isEmpty) {
    buffer.writeln('const Map<String, String> bundledRecipeFiles = {};');
    return buffer.toString();
  }
  buffer.writeln('const Map<String, String> bundledRecipeFiles = {');
  for (final MapEntry(key: name, value: yaml) in files.entries) {
    if (yaml.contains("'''")) {
      throw FormatException("$name contains ''' which can't be embedded.");
    }
    buffer.writeln("  '$name': r'''");
    buffer.write(yaml.endsWith('\n') ? yaml : '$yaml\n');
    buffer.writeln("''',");
  }
  buffer.writeln('};');
  return buffer.toString();
}
